{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Thalidomide, a heterocyclic imide with slow oral absorption, has probably high absolute oral bioavailability (80–100%) at 100 mg in fasting healthy volunteers; this supports high F for the similarly slowly absorbed tricyclic carbamazepine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Saccharin administered in the fed state had an absolute fraction absorbed of 0.80±0.05 vs i.v., providing direct fed-state evidence that oral bioavailability exceeds 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Tocainide has about 100% absolute oral bioavailability in healthy volunteers, supporting essentially complete absorption for a small polar amide-containing drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Temozolomide oral bioavailability is close to 100% vs IV at 150 mg/m2, supporting high F for an orally absorbed heterocyclic carboxamide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C62"],
      "claim": "Ampicillin oral bioavailability is 30–50% in humans; although incomplete, this is still above the 20% threshold and therefore supports a high classification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Sulpiride mean oral bioavailability is ~35% (range 10–70%), again above the 20% threshold and supportive of high classification despite variable absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Phenylbutyrate oral bioavailability was 78% in patients with solid tumors, supporting high F for a small aromatic compound.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved high-transfer evidence supports F≥20%: absolute oral bioavailability values range from ~30–100%, including fed-state saccharin (80%), thalidomide (80–100%), tocainide (~100%), temozolomide (~100%), phenylbutyrate (78%), and even incompletely absorbed ampicillin/sulpiride (30–62%). No evidence supports F<20%.",
  "evidence_gaps": [
    "No direct carbamazepine-specific bioavailability record is present in the supplied evidence; prediction relies on high-transfer analogues.",
    "Fed-state absolute bioavailability for the query is not directly measured; only saccharin provides a fed-state absolute F measurement."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

